var meanings = map[int]string{
	1:  "ชื่อค่าเลขศาสตร์ 1 ราชาแห่งจักรวาล เป็นสัญญลักษณ์ของลูกคนโตมีเกียรติมีอำนาจมีวาสนามีบารมี รักความก้าวหน้ารักอิสระเปิดเผยตรงไปตรงมา เป็นคนมีความรับผิดชอบสูงไม่ชอบให้ใครมาบังคับมีอิสระทางความคิดมักจะรุ่งเรืองในหน้าที่การงานเป็นคนที่เพื่อนร่วมงานไว้วางใจได้ไม่ชอบให้ใครมาสอนมาบ่นจู้จี้จุกจิกให้รำคาญใจ(แต่ตัวเองกลับชอบสอนชอบบ่นเสียเอง)เป็นคนตรงไปตรงมากล้าสู้กล้าเผชิญกับความจริงไม่ชอบเสแสร้งไม่ชอบคนปากหวานก้นเปรี้ยวถ้าใครจริงใจมาก็จะได้รับการช่วยเหลืออย่างเต็มที่เท่าไหร่เท่ากัน ข้อเสียของหมายเลขนี้คือดูเป็นคนหยิ่งจองหองถือดี(แต่จริงๆแล้วเป็นคนใจอ่อนขี้สงสารชอบช่วยเหลือคนที่อ่อนแอกว่าหรือคนที่ถูกรังแก)ชอบเอาภาระ หรือปัญหาของคนอื่นมาเป็นภาระของตัวเอง(จึงมักจะถูกหลอกได้ง่ายๆเช่นกัน)ใจร้อนขี้โมโหหุนหันพลันแล่นโกรธเร็วเจ็บแล้วไม่รู้จักจำมักหลงตัวเองก้าวร้าวรักศักดิ์ศรีเป็นที่หนึ่ง(จึงเหมาะที่จะเป็นนักปกครองถ่อมตัวไม่เป็น)ชีวิตเต็มไปด้วยความเปลี่ยนแปลงและการเดินทางชีวิตของคนหมายเลขนี้มักว้าเหว่ด้วยไม่ค่อยสบอารมณ์ต่อสิ่งใดง่ายๆหากเป็นสตรีก็การมีคู่ที่เด่นๆซึ่งก็ไม่ค่อยเป็นผลให้สมปรารถนาในชีวิตชีวิตมักเคลื่อนไหวไม่อยู่นิ่งเต็มไปด้วยการเปลี่ยนแปลงการเดินทางและการพลัดพรากสุขภาพควรระวังโรคหัวใจทุกรูปแบบระวังโรคเกี่ยวกับความดันโลหิตโรคเกี่ยวกับตา",
	2:  "ชื่อค่าเลขศาสตร์ 2 ราชินีแห่งจักรวาล สะอาดเรียบร้อยน่ารักดูสุภาพอ่อนโยนโรแมนติกชอบบริการชอบช่วยเหลือคนปรับตัวเก่งเหมาะที่จะเป็นนักพูดนักแสดงเพราะกล้าพูดกล้าทำ(มักเป็นคนที่	อยู่เบื้องหลังยุคนอื่นเก่ง)มีญาณหรือลางสังหรณ์ดีเก็บความลับได้ดีและสามารถล้วงความลับของคนอื่นได้ดีเช่นกันเป็นคนรักบ้านมีความผูกพันกับบ้านมากและส่วนมากจะมีความผูกพันกับแม่มากกว่าพ่อและเมื่อได้มีโอกาสได้เป็นพ่อคนแม่คนแล้วก็จะเป็นพ่อแม่ที่ดีของลูกมากส่วนมากมักจะรักลูกมากเกินไปประคบประหงมลูกยิ่งกว่าไข่ในหิน ข้อเสียของบุคคลหมายเลขนี้คือชอบคิดชอบฝันมักมีแผนการณ์เยอะแต่ไม่ค่อยลงมือกระทำจริงจัง มีอารมณ์อ่อนไหวง่ายคล้อยตามเสียงส่วนใหญ่กลัวความไม่แน่นอนกลัวความผิดหวังกลัวการพลัดพรากสูญเสียกลัวถูกทอดทิ้ง กลัวไม่มีงานทำ อ่อนแอหูเบา ใจน้อยแสนงอนเหมือนเป็นโรคประสาทอ่อนๆ สุขภาพมักอ่อนแอขี้โรค ระวังกระเพาะอาหาร ระบบการย่อยอาหาร ระบบขับถ่าย โรคประสาท โรคเกี่ยวกับตาถ้าเป็นผู้หญิงต้องระวังโรคเกี่ยวกับอวัยวะสตรี มดลูก รังไข่",
	3:  "ชื่อค่าเลขศาสตร์ 3 เทพเจ้าแห่งสงคราม เป็นเลขร้ายโหราศาสตร์ไทยถือว่าเป็นตัวฆาตตัวจู่โจมทะลุทะลวงความปั่นป่วนการทะเลาะวิวาทสงคราม บ่งบอกถึงการขัดแย้งอย่างรุนแรง การผ่าตัด อุบัติเหตุ*ข้อดีของบุคคลหมายเลขนี้คือมีความขยันขันแข็งกล้าหาญเด็ดเดี่ยวการแสดงออกอย่างเปิดเผยกล้าได้กล้าเสียมีความอดทนเป็นเลิศรักอิสระชอบเรียนรู้ชอบทำมากกว่าคิดรักความยุติธรรมใจกว้างกับผู้กระทำผิดเป็นคนมองโลกในแง่ดีเกลียดพวกหน้าไหว้หลังหลอก ข้อเสียของบุคคลหมายเลขนี้คือเป็นคนไม่รอบคอบใจร้อนโทสะแรง ทำแล้วจึงค่อยมาคิดใจนักเลง ชอบพูดจาขวานผ่าซาก เป็นคนขี้เบื่อไม่ชอบทำอะไรซ้ำซาก ชอบเสี่ยง ชอบลอง บางครั้งการที่รักอิสระมากเกินไป เราอาจเห็นเขาทำตัวเหมือนพวงมาลัยลอยไปลอยมาแบบไม่มีแก่น เป็นคนแปลกมาก บทจะเชื่ออะไรก็เชื่อง่ายๆ แต่บทจะไม่เชื่อ ต่อให้เอาอะไรมาอ้างก็จะไม่ยอมเชื่อเด็ดขาดสุขภาพระวังโรคเกี่ยวกับทางเพศสัมพันธ์โรคภูมิแพ้โรคประสาทเพราะทำงานหนักมากเกินไปอาการปวดสะโพกรวมทั้งปัญหาผิวหนังหลายรูปแบบ..",
	4:  "ชื่อค่าเลขศาสตร์ 4 เทพแห่งการสื่อสารการพาณิชย์ เทพดาวพุธผุ้เฉลียวฉลาดช่างคิดช่างพูดรอบรู้ความจำดีเชื่อมั่นในตัวเองสูงไม่ชอบให้ใครท้าทายมีความคิดอ่านล้ำยุคจนผู้อื่นตามไม่ทันเป็นนักเลียนแบบตัวยงด้วยและเมื่อเลียนแบบแล้วจะนำมาประยุกต์ใช้จนกลายเป็นเอกลักษณ์ของตัวเองเป็นคนปรับตัวเก่งเข้าตำราอยู่กับฤาษีก็เป็นนักปราชญ์อยู่กับคนคดก็คดตามด้วยฉะนั้นบุคคลหมายเลขนี้ต้องระวังเรื่องการติดของเสพติดทุกอย่างเป็นคนที่ไม่ชอบยุ่งกับชีวิตส่วนตัวของใครและหวังว่าคนอื่นก็ไม่ควรมาวุ่นวายกับชีวิตของเขาเช่นกัน จุดบอดของบุคคลหมายเลขนี้คือความไม่แน่นอนในทางโหราศาสตร์ไทยถือว่าดาวพุธเป็นดาวแห่งความรวนเรมีความคิดเห็นแปลกๆตรงกันข้ามกับคนทั่วไปชอบทำอะไรตามกฎเกณฑ์ของตัวเองพูดจาโฉ่งฉ่างเสียงดังมีสัญชาติญาณแห่งการเปลี่ยนแปลงแบบพิศดารจนดูเหมือนเป็นมนุษย์เจ้าปัญหาจนบางทีสร้างความอึดอัดให้แก่คนรอบข้างปากพูดไปเรื่อยพูดมากเกินไปหลายครั้งก่อศัตรูขึ้นก็เพราะปากของตนเองสุขภาพควรระวังโรคที่ลึกลับยากแก่รักษาโรคที่เกี่ยวกับช่องท้องโรคประสาท โรคเกี่ยวกับกล่องเสียงพูดติดอ่างพูดไม่ชัด",
	15: "ใส่ความหมายของเลข 15 ที่นี่",
	// 20: "ใส่ความหมายของเลข 20 ที่นี่",
	// 35: "ใส่ความหมายของเลข 35 ที่นี่",
}

func meaningFor(n int) string {
	if m, ok := meanings[n]; ok && m != "" {
		return m
	}
	return fmt.Sprintf("(ยังไม่มีความหมายของเลข %d ในตาราง meanings)", n)
}
